@SpringBootApplication
public class SqsConsumerApplication {

    public static void main(String[] args) {
        SpringApplication.run(SqsConsumerApplication.class, args);
    }

    @SqsListener("order-processing-queue")
    public void receiveOrderMessage(@Payload OrderPayload payload, @Header("SqsMessageId") String messageId) {
        // Process incoming cloud message with native deserialization
        processOrder(payload);
    }
}

